SELECT txn_type, COUNT(*) n, SUM(written_premium) wp, MIN(effective_date) mn, MAX(cover_end_date) mx, COUNT(DISTINCT region) FROM premium_txn JOIN policy_term USING (term_id) GROUP BY 1 ORDER BY 1;
SELECT region, COUNT(*) FROM policy_term GROUP BY 1;
SELECT DISTINCT region FROM policy;
